<style>
.hr-wrap{font-family:Inter,Arial,sans-serif;color:#25313c}.hr-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:20px}.hr-title{font-size:22px;font-weight:700;color:#123b5d}.hr-sub{color:#64748b;font-size:13px;margin-top:4px}.hr-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-bottom:18px}.hr-card{background:#fff;border:1px solid #cbd5e1;border-radius:14px;padding:18px;margin-bottom:16px}.hr-kpi{font-size:26px;font-weight:700;color:#123b5d;margin-top:8px}.hr-label{font-size:12px;font-weight:600;color:#64748b}.hr-btn{display:inline-block;background:#fff;border:1px solid #cbd5e1;border-radius:9px;padding:9px 13px;color:#123b5d;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.hr-primary{background:#123b5d;color:#fff;border-color:#123b5d}.hr-input{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:9px 10px;font-size:13px;background:white}.hr-formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.hr-field label{display:block;font-size:12px;font-weight:600;color:#475569;margin-bottom:5px}.hr-table{width:100%;border-collapse:collapse;font-size:13px}.hr-table th{text-align:left;color:#64748b;background:#f8fafc;font-size:11px;text-transform:uppercase;letter-spacing:.03em}.hr-table th,.hr-table td{padding:11px 10px;border-bottom:1px solid #e2e8f0;vertical-align:middle}.hr-pill{display:inline-block;border-radius:20px;padding:4px 9px;background:#f1f5f9;color:#475569;font-size:11px;font-weight:600}.hr-actions{display:flex;gap:8px;flex-wrap:wrap}.hr-muted{color:#64748b;font-size:12px}.hr-alert{padding:10px 13px;background:#ecfdf5;color:#166534;border-radius:8px;margin-bottom:12px;font-size:13px}@media(max-width:650px){.hr-head{align-items:flex-start;flex-direction:column}.hr-card{overflow-x:auto}}
</style>
